import 'dart:convert';
import 'dart:typed_data';
import 'package:flutter/material.dart';

/// Embedded Official EOTO Logos (Transparent PNG)
/// Decoded directly from optimized in-memory bytes to guarantee 100% instant rendering
/// across all platforms (Flutter Web, Android, iOS) without any asset bundle reload issues.
class AppLogos {
  // Official Black Horizontal Transparent Wordmark
  static final Uint8List _wordmarkBytes = base64Decode('');

  // Official Lime Transparent Emblem
  static final Uint8List _emblemBytes = base64Decode('');

  /// Returns the official transparent horizontal EOTO logo (black with star/crescent)
  static Widget wordmark({double height = 28, BoxFit fit = BoxFit.contain}) {
    return Image.memory(
      _wordmarkBytes,
      height: height,
      fit: fit,
      filterQuality: FilterQuality.high,
    );
  }

  /// Returns the official transparent EOTO emblem
  static Widget emblem({double height = 48, BoxFit fit = BoxFit.contain}) {
    return Image.memory(
      _emblemBytes,
      height: height,
      fit: fit,
      filterQuality: FilterQuality.high,
    );
  }
}
